package br.com.setedasorte.controller;
import br.com.setedasorte.model.*;import br.com.setedasorte.repo.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
@RestController @RequestMapping("/api") public class LeilaoController{
 private final LeilaoRepository leiloes;private final UsuarioRepository usuarios;private final LanceRepository lances;private final PagamentoRepository pagamentos;
 public LeilaoController(LeilaoRepository l,UsuarioRepository u,LanceRepository a,PagamentoRepository p){leiloes=l;usuarios=u;lances=a;pagamentos=p;}
 record LD(Long id,String titulo,String categoria,String descricao,String imagem,BigDecimal lanceInicial,BigDecimal lanceAtual,LocalDateTime encerraEm,boolean ativo,boolean encerrado){}
 record BID(Long id,String nome,BigDecimal valor,LocalDateTime criadoEm){}
 record NovoLeilao(@NotBlank String titulo,@NotBlank String categoria,@NotBlank String descricao,@NotBlank String imagem,@NotNull @DecimalMin("0.01") BigDecimal lanceInicial,@NotNull LocalDateTime encerraEm){}
 record NovoLance(@NotNull @DecimalMin("0.01") BigDecimal valor){}
 private LD dto(Leilao l){return new LD(l.getId(),l.getTitulo(),l.getCategoria(),l.getDescricao(),l.getImagem(),l.getLanceInicial(),l.getLanceAtual(),l.getEncerraEm(),l.isAtivo(),l.encerrado());}
 @GetMapping("/leiloes") public List<LD> all(@RequestParam(required=false)String categoria,@RequestParam(required=false)String busca){List<Leilao> a=(categoria!=null&&!categoria.isBlank())?leiloes.findByCategoriaIgnoreCaseOrderByEncerraEmAsc(categoria):leiloes.findAllByOrderByEncerraEmAsc();if(busca!=null&&!busca.isBlank())a=a.stream().filter(l->l.getTitulo().toLowerCase().contains(busca.toLowerCase())||l.getDescricao().toLowerCase().contains(busca.toLowerCase())).toList();return a.stream().map(this::dto).toList();}
 @GetMapping("/leiloes/{id}") public ResponseEntity<?> one(@PathVariable Long id){return leiloes.findById(id).<ResponseEntity<?>>map(l->ResponseEntity.ok(Map.of("leilao",dto(l),"lances",lances.findTop20ByLeilaoIdOrderByCriadoEmDesc(id).stream().map(a->new BID(a.getId(),a.getUsuario().getNome(),a.getValor(),a.getCriadoEm())).toList()))).orElse(ResponseEntity.notFound().build());}
 @PostMapping("/leiloes/{id}/lances") @Transactional public ResponseEntity<?> bid(@PathVariable Long id,@Valid @RequestBody NovoLance b,Authentication auth){Usuario u=usuarios.findByEmailIgnoreCase(auth.getName()).orElseThrow();Leilao l=leiloes.findById(id).orElse(null);if(l==null)return ResponseEntity.notFound().build();if(l.encerrado())return ResponseEntity.badRequest().body(Map.of("message","Este leilão já foi encerrado."));if(b.valor().compareTo(l.getLanceAtual())<=0)return ResponseEntity.badRequest().body(Map.of("message","O lance precisa ser maior que o lance atual."));l.setLanceAtual(b.valor());l.setVencedorId(u.getId());leiloes.save(l);lances.save(new Lance(l,u,b.valor()));return ResponseEntity.ok(Map.of("message","Lance registrado!","lanceAtual",l.getLanceAtual()));}
 @PostMapping("/admin/leiloes") public ResponseEntity<?> create(@Valid @RequestBody NovoLeilao b){if(!b.encerraEm().isAfter(LocalDateTime.now()))return ResponseEntity.badRequest().body(Map.of("message","A data de encerramento deve estar no futuro."));return ResponseEntity.ok(dto(leiloes.save(new Leilao(b.titulo(),b.categoria(),b.descricao(),b.imagem(),b.lanceInicial(),b.encerraEm()))));}
 @GetMapping("/usuario/lances") public List<?> myBids(Authentication a){Usuario u=usuarios.findByEmailIgnoreCase(a.getName()).orElseThrow();return lances.findByUsuarioIdOrderByCriadoEmDesc(u.getId()).stream().map(x->Map.of("leilao",x.getLeilao().getTitulo(),"valor",x.getValor(),"criadoEm",x.getCriadoEm(),"leilaoId",x.getLeilao().getId())).toList();}
 @GetMapping("/usuario/pagamentos") public List<?> payments(Authentication a){Usuario u=usuarios.findByEmailIgnoreCase(a.getName()).orElseThrow();return pagamentos.findByUsuarioIdOrderByCriadoEmDesc(u.getId()).stream().map(p->Map.of("id",p.getId(),"produto",p.getLeilao().getTitulo(),"valor",p.getValor(),"status",p.getStatus(),"metodo",p.getMetodo(),"criadoEm",p.getCriadoEm())).toList();}
 @PostMapping("/leiloes/{id}/pagamento-simulado") public ResponseEntity<?> pay(@PathVariable Long id,Authentication a,@RequestBody Map<String,String> b){Usuario u=usuarios.findByEmailIgnoreCase(a.getName()).orElseThrow();Leilao l=leiloes.findById(id).orElse(null);if(l==null)return ResponseEntity.notFound().build();if(l.getVencedorId()==null||!l.getVencedorId().equals(u.getId())||!l.encerrado())return ResponseEntity.badRequest().body(Map.of("message","Pagamento disponível apenas ao vencedor após o encerramento."));Pagamento p=pagamentos.save(new Pagamento(u,l,l.getLanceAtual(),b.getOrDefault("metodo","PIX DEMONSTRATIVO")));return ResponseEntity.ok(Map.of("message","Pagamento simulado. Nenhum dinheiro foi movimentado.","status",p.getStatus(),"id",p.getId()));}
}
